def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    import re as _re
    blob = json.dumps({"l": lessons, "q": questions}, ensure_ascii=False)
    if "ERPNext" in blob:
        problems.append(f"  {name}: ERPNext branding leakage")
    if _re.search(r"\b[Ll]aws?\b", blob):
        problems.append(f"  {name}: 'law' register leakage")
    low = blob.lower()
    for marker in ["certified professional", "the consultant", "consultants", "the academy",
                   "this academy", "engagement", "constitution", "costume", "scar tissue",
                   "witness", "testimony"] + EDITORIAL_BAN:
        if marker in low:
            problems.append(f"  {name}: banned phrase '{marker}'")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.197.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.196.0"' not in init:
        sys.exit("ABORT: not at v3.196.0.")
    if "material_requests" not in data:
        sys.exit("ABORT: material_requests module not found in data file.")

    problems = _validate("PROC3", LESSONS_P3, QUESTIONS_P3, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS_P3))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — PROC3 spread failed: {dist}")
        sys.exit(1)
    total = sum(len(l["html"]) for l in LESSONS_P3)
    print(f"PROC 3 v3: {len(LESSONS_P3)} chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS_P3):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["material_requests"]["lessons"] = LESSONS_P3
    data["material_requests"]["questions"] = bank
    data["material_requests"]["desc"] = ("Material Requests and the demand machinery in ZhiftERP: the field walk — type routing, need dates, justifications, and the status life; the three demand sources — manual requests, reorder auto-generation on projected quantity with the computation as justification, and order-driven demand; the screening step — stock elsewhere first, the need as stated, size and date, budget and policy — with the approval-band separation and the purchases-avoided figure; consolidation — the worksheet, the ordering arithmetic with written adjustments, the date and destination structures, the request-to-order trace, and the window discipline; transfer and issue requests with the cascade rule from branch demand to hub purchasing; and the five demand reads including the quarterly trace audit.")

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.196.0"', '"3.197.0"'))
    print("  data: PROCUREMENT 3 lessons + bank REPLACED (style v3, textbook manual register)")
    print("wrote __version__ -> 3.197.0")


if __name__ == "__main__":
    main()
